function $(s, c) {
  return (c || document).querySelector(s);
}
function $$(s, c) {
  return Array.prototype.slice.call((c || document).querySelectorAll(s));
}
var finePointer = window.matchMedia("(pointer: fine)").matches;
var reducedMotion = window.matchMedia(
  "(prefers-reduced-motion: reduce)",
).matches;
var hasGsap = typeof gsap !== "undefined";
if (hasGsap && typeof ScrollTrigger !== "undefined")
  gsap.registerPlugin(ScrollTrigger);
$("#year").textContent = new Date().getFullYear();

/* Lenis */
var lenis = null;
if (typeof Lenis !== "undefined" && !reducedMotion) {
  lenis = new Lenis({ duration: 1.3, smoothWheel: true, lerp: 0.09 });
  if (hasGsap && typeof ScrollTrigger !== "undefined") {
    lenis.on("scroll", ScrollTrigger.update);
    gsap.ticker.add(function (t) {
      lenis.raf(t * 1000);
    });
    gsap.ticker.lagSmoothing(0);
  } else {
    (function raf(t) {
      lenis.raf(t);
      requestAnimationFrame(raf);
    })(0);
  }
}
function scrollToTarget(sel) {
  var el = document.querySelector(sel);
  if (!el) return;
  if (lenis) lenis.scrollTo(el, { offset: -70, duration: 1.3 });
  else el.scrollIntoView({ behavior: "smooth" });
}
$$('a[href^="#"]').forEach(function (a) {
  a.addEventListener("click", function (e) {
    var h = a.getAttribute("href");
    if (h.length > 1 && document.querySelector(h)) {
      e.preventDefault();
      closeMobile();
      scrollToTarget(h);
    }
  });
});

/* nav state */
addEventListener(
  "scroll",
  function () {
    $("#navbar").classList.toggle(
      "scrolled",
      scrollY > window.innerHeight - 90,
    );
  },
  { passive: true },
);

/* mobile menu */
var mobileMenu = $("#mobileMenu");
function openMobile() {
  mobileMenu.classList.add("open");
  if (lenis) lenis.stop();
  document.body.style.overflow = "hidden";
}
function closeMobile() {
  if (!mobileMenu.classList.contains("open")) return;
  mobileMenu.classList.remove("open");
  if (lenis) lenis.start();
  document.body.style.overflow = "";
}
$("#burger").addEventListener("click", openMobile);
$("#closeMenu").addEventListener("click", closeMobile);

/* story toggle — smooth height expand */
$("#storyToggle").addEventListener("click", function () {
  var m = $("#storyMore"),
    open = !m.classList.contains("open");
  this.setAttribute("aria-expanded", open);
  this.textContent = open ? "Close our story ↑" : "Read our story →";
  if (open) {
    m.classList.remove("hidden");
    requestAnimationFrame(function () {
      m.style.maxHeight = m.scrollHeight + "px";
      m.classList.add("open");
    });
    setTimeout(function () {
      m.style.maxHeight = "none";
      if (typeof ScrollTrigger !== "undefined") ScrollTrigger.refresh();
    }, 850);
  } else {
    m.style.maxHeight = m.scrollHeight + "px";
    requestAnimationFrame(function () {
      m.style.maxHeight = "0px";
      m.classList.remove("open");
    });
    setTimeout(function () {
      m.classList.add("hidden");
      if (typeof ScrollTrigger !== "undefined") ScrollTrigger.refresh();
    }, 850);
  }
});

/* collection carousel */
var colStage = $("#colStage"),
  colIdx = 0;
colStage.innerHTML = COLLECTION.map(function (c, i) {
  return (
    '<article class="col-card' +
    (i === 0 ? " active" : "") +
    '"><div class="ph"><img src="' +
    c.img +
    '" alt="' +
    c.tag +
    " — " +
    c.name +
    '"' +
    (i ? ' loading="lazy"' : "") +
    '></div><div class="body"><small>' +
    c.tag +
    "</small><h3>" +
    c.name +
    "</h3><p>" +
    c.desc +
    '</p><p class="meta">' +
    c.meta +
    '</p><div><button type="button" data-reserve class="btn btn-outline" style="min-height:48px;padding:.8rem 1.6rem">Reserve</button></div></div></article>'
  );
}).join("");
$("#colDots").innerHTML = COLLECTION.map(function (_, i) {
  return (
    '<button type="button" aria-label="Collection ' +
    (i + 1) +
    '" data-i="' +
    i +
    '"' +
    (i === 0 ? ' class="active"' : "") +
    "></button>"
  );
}).join("");
function colGo(i) {
  colIdx = (i + COLLECTION.length) % COLLECTION.length;
  $$(".col-card", colStage).forEach(function (c, ci) {
    c.classList.toggle("active", ci === colIdx);
  });
  $$("#colDots button").forEach(function (d, di) {
    d.classList.toggle("active", di === colIdx);
  });
  $("#colCount").textContent = colIdx + 1 + " / " + COLLECTION.length;
  $("#colPrev").disabled = colIdx === 0;
  $("#colNext").disabled = colIdx === COLLECTION.length - 1;
}
$("#colPrev").addEventListener("click", function () {
  colGo(colIdx - 1);
});
$("#colNext").addEventListener("click", function () {
  colGo(colIdx + 1);
});
$$("#colDots button").forEach(function (d) {
  d.addEventListener("click", function () {
    colGo(parseInt(d.getAttribute("data-i"), 10));
  });
});
colGo(0);

/* quotes carousel */
var qStage = $("#quoteStage"),
  qIdx = 0;
qStage.innerHTML = QUOTES.map(function (q, i) {
  return (
    '<div class="quote-slide' +
    (i === 0 ? " active" : "") +
    '"><blockquote>' +
    q.text +
    "</blockquote><cite>" +
    q.cite +
    "</cite></div>"
  );
}).join("");
function qGo(i) {
  qIdx = (i + QUOTES.length) % QUOTES.length;
  $$(".quote-slide", qStage).forEach(function (s, si) {
    s.classList.toggle("active", si === qIdx);
  });
  $("#quoteCount").textContent = qIdx + 1 + " / " + QUOTES.length;
}
$("#quotePrev").addEventListener("click", function () {
  qGo(qIdx - 1);
});
$("#quoteNext").addEventListener("click", function () {
  qGo(qIdx + 1);
});
setInterval(function () {
  if (!document.hidden) qGo(qIdx + 1);
}, 7000);

/* menu */
var activeCat = "all",
  activeDiets = {};
var menuGrid = $("#menuGrid"),
  menuEmpty = $("#menuEmpty");
function dietChips(d) {
  return d.diets
    .map(function (x) {
      return (
        "<span" +
        (x === "halal" ? ' class="clay"' : "") +
        ">" +
        DIET_LABELS[x] +
        "</span>"
      );
    })
    .join("");
}
function renderMenu(animate) {
  var list = DISHES.filter(function (d) {
    if (activeCat !== "all" && d.cat !== activeCat) return false;
    for (var k in activeDiets) {
      if (activeDiets[k] && d.diets.indexOf(k) === -1) return false;
    }
    return true;
  });
  menuGrid.innerHTML = list
    .map(function (d, i) {
      return (
        '<article class="dish-card" data-id="' +
        d.id +
        '" tabindex="0" role="button" aria-label="View ' +
        d.name +
        '"><div class="thumb"><img src="' +
        d.img +
        '" alt="' +
        d.name +
        '"' +
        (i < 6 ? "" : ' loading="lazy"') +
        '><span class="price-chip">£' +
        d.price +
        '</span></div><div class="body"><p class="cat">' +
        CAT_LABELS[d.cat] +
        "</p><h3>" +
        d.name +
        '</h3><p class="desc">' +
        d.desc +
        '</p><div class="dish-tags">' +
        dietChips(d) +
        "</div></div></article>"
      );
    })
    .join("");
  menuEmpty.classList.toggle("hidden", list.length > 0);
  menuGrid.classList.toggle("hidden", list.length === 0);
  bindCards();
  if (animate && hasGsap && !reducedMotion)
    gsap.from("#menuGrid .dish-card", {
      y: 26,
      opacity: 0,
      duration: 0.55,
      stagger: 0.04,
      ease: "power3.out",
      clearProps: "transform,opacity",
    });
  if (typeof ScrollTrigger !== "undefined") ScrollTrigger.refresh();
}
$$("#categoryTabs .filter-pill").forEach(function (b) {
  b.addEventListener("click", function () {
    $$("#categoryTabs .filter-pill").forEach(function (x) {
      x.classList.remove("active");
    });
    b.classList.add("active");
    activeCat = b.getAttribute("data-cat");
    renderMenu(true);
  });
});
$$(".diet-pill").forEach(function (b) {
  b.addEventListener("click", function () {
    var d = b.getAttribute("data-diet");
    activeDiets[d] = !activeDiets[d];
    b.classList.toggle("active", activeDiets[d]);
    renderMenu(true);
  });
});
$("#clearDiets").addEventListener("click", function () {
  activeDiets = {};
  $$(".diet-pill").forEach(function (b) {
    b.classList.remove("active");
  });
  renderMenu(true);
});

/* floating preview */
var preview = $("#dishPreview"),
  previewImg = $("#dishPreviewImg");
if (finePointer && hasGsap && !reducedMotion) {
  gsap.set(preview, { scale: 0.94, transformOrigin: "center center" });
  var pxTo = gsap.quickTo(preview, "x", { duration: 0.65, ease: "power3" }),
    pyTo = gsap.quickTo(preview, "y", { duration: 0.65, ease: "power3" });
  var prTo = gsap.quickTo(preview, "rotation", {
    duration: 0.8,
    ease: "power3",
  });
  var lastX = window.innerWidth / 2;
  document.addEventListener("mousemove", function (e) {
    pxTo(e.clientX + 24);
    pyTo(e.clientY - 135);
    prTo(gsap.utils.clamp(-5, 5, (e.clientX - lastX) * 0.12));
    lastX = e.clientX;
  });
}
function bindCards() {
  $$(".dish-card").forEach(function (card) {
    var dish = DISHES.filter(function (d) {
      return d.id == card.getAttribute("data-id");
    })[0];
    if (!dish) return;
    card.addEventListener("mouseenter", function () {
      if (!finePointer) return;
      previewImg.src = dish.img;
      if (hasGsap && !reducedMotion)
        gsap.to(preview, {
          autoAlpha: 1,
          scale: 1,
          duration: 0.45,
          ease: "power3.out",
        });
      else preview.style.opacity = "1";
    });
    card.addEventListener("mouseleave", function () {
      if (hasGsap && !reducedMotion)
        gsap.to(preview, {
          autoAlpha: 0,
          scale: 0.94,
          duration: 0.35,
          ease: "power3.in",
        });
      else preview.style.opacity = "0";
    });
    card.addEventListener("click", function () {
      openDish(dish);
    });
    card.addEventListener("keydown", function (e) {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        openDish(dish);
      }
    });
  });
}
renderMenu(false);

/* modals lock */
function lockScroll(v) {
  document.documentElement.style.overflow = v ? "hidden" : "";
  document.body.style.overflow = v ? "hidden" : "";
  if (lenis) {
    v ? lenis.stop() : lenis.start();
  }
}

/* dish modal */
var dishModal = $("#dishModal");
function openDish(dish) {
  $("#dishImg").src = dish.img;
  $("#dishImg").alt = dish.name;
  $("#dishCat").textContent = CAT_LABELS[dish.cat];
  $("#dishTitle").textContent = dish.name;
  $("#dishPrice").textContent = "£" + dish.price;
  $("#dishDesc").textContent = dish.desc;
  $("#dishIngredients").innerHTML = dish.ingredients
    .map(function (i) {
      return "<li>" + i + "</li>";
    })
    .join("");
  $("#dishPairing").textContent = dish.pairing;
  dishModal.classList.add("open");
  lockScroll(true);
  if (hasGsap) gsap.to(preview, { autoAlpha: 0, duration: 0.2 });
  else preview.style.opacity = "0";
}
function closeDish() {
  dishModal.classList.remove("open");
  lockScroll(false);
}
$$("[data-close-dish]").forEach(function (el) {
  el.addEventListener("click", closeDish);
});

/* film modal */
var filmModal = $("#filmModal"),
  filmTimer = null,
  filmIdx = 0;
function openFilm() {
  filmModal.classList.add("open");
  lockScroll(true);
  filmIdx = 0;
  var imgs = $$("#filmFrame img");
  imgs.forEach(function (im, i) {
    im.classList.toggle("on", i === 0);
  });
  filmTimer = setInterval(function () {
    imgs[filmIdx].classList.remove("on");
    filmIdx = (filmIdx + 1) % imgs.length;
    imgs[filmIdx].classList.add("on");
  }, 2600);
}
function closeFilm() {
  filmModal.classList.remove("open");
  lockScroll(false);
  if (filmTimer) clearInterval(filmTimer);
}
$("#playFilm").addEventListener("click", openFilm);
$$("[data-close-film]").forEach(function (el) {
  el.addEventListener("click", closeFilm);
});

/* signature strip */
