/* newsletter */
$("#newsletterForm").addEventListener("submit", function (e) {
  e.preventDefault();
  var email = $("#newsletterEmail").value.trim(),
    msg = $("#newsletterMsg");
  msg.style.display = "block";
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    msg.style.color = "#B4552D";
    msg.textContent = "Please enter a valid email address.";
    return;
  }
  msg.style.color = "var(--accent-d)";
  msg.textContent =
    "Welcome to the table — your first story from the kitchen arrives with the new season.";
  this.reset();
});

/* reservation */
var reserveModal = $("#reserveModal");
var res = {
  guests: 2,
  guestsLabel: "2",
  date: "",
  period: "dinner",
  slot: null,
};
var curStep = 1;
function fmtDate(iso) {
  if (!iso) return "—";
  var d = new Date(iso + "T12:00:00");
  return d.toLocaleDateString("en-GB", {
    weekday: "long",
    day: "numeric",
    month: "long",
    year: "numeric",
  });
}
function hashCode(str) {
  var h = 0;
  for (var i = 0; i < str.length; i++) {
    h = ((h << 5) - h + str.charCodeAt(i)) | 0;
  }
  return Math.abs(h);
}
function slotRange(iso, period) {
  var d = new Date(iso + "T12:00:00"),
    day = d.getDay();
  if (day === 1) return null;
  if (period === "lunch") {
    return day === 0 ? ["12:30", "15:00"] : ["12:00", "14:30"];
  }
  if (day === 0) return ["17:30", "21:30"];
  if (day === 5 || day === 6) return ["17:30", "23:00"];
  return ["17:30", "22:30"];
}
function toMinutes(t) {
  var p = t.split(":");
  return parseInt(p[0], 10) * 60 + parseInt(p[1], 10);
}
function toTime(m) {
  var h = Math.floor(m / 60),
    mm = m % 60;
  return (h < 10 ? "0" : "") + h + ":" + (mm < 10 ? "0" : "") + mm;
}
function buildSlots() {
  var grid = $("#slotGrid"),
    notice = $("#slotNotice");
  grid.innerHTML = "";
  notice.classList.add("hidden");
  res.slot = null;
  $("#slotContext").textContent = res.date
    ? fmtDate(res.date) + " · " + (res.period === "lunch" ? "Lunch" : "Dinner")
    : "";
  var range = res.date ? slotRange(res.date, res.period) : null;
  if (res.date && !range) {
    notice.classList.remove("hidden");
    notice.querySelector("span").textContent =
      "Qissa is closed on Mondays. Please choose another date — we would love to host you.";
    return;
  }
  if (!range) return;
  var seed = hashCode(res.date + res.period),
    slots = [];
  for (var t = toMinutes(range[0]); t <= toMinutes(range[1]); t += 30)
    slots.push(toTime(t));
  var fullCount = 0;
  slots.forEach(function (s, i) {
    var full = ((seed >> (i % 12)) & 1) === 1 && (seed + i * 7) % 3 !== 0;
    if (full) fullCount++;
    if (fullCount > slots.length - 3) full = false;
    var b = document.createElement("button");
    b.type = "button";
    b.className = "slot-pill" + (full ? " full" : "");
    b.textContent = s;
    if (full) {
      b.disabled = true;
      b.setAttribute("aria-label", s + " — fully booked");
    } else {
      b.addEventListener("click", function () {
        $$("#slotGrid .slot-pill").forEach(function (x) {
          x.classList.remove("selected");
        });
        b.classList.add("selected");
        res.slot = s;
        hideError();
      });
    }
    grid.appendChild(b);
  });
}
function updateSummary() {
  $("#sumGuests").textContent =
    res.guestsLabel + (res.guests === 1 ? " guest" : " guests");
  $("#sumDate").textContent = fmtDate(res.date);
  $("#sumTime").textContent = res.slot
    ? res.slot + " · " + (res.period === "lunch" ? "Lunch" : "Dinner")
    : "—";
}
function showError(t) {
  var e = $("#stepError");
  e.textContent = t;
  e.classList.remove("hidden");
}
function hideError() {
  $("#stepError").classList.add("hidden");
}
function goStep(n) {
  curStep = n;
  $$(".step-panel").forEach(function (p) {
    p.classList.toggle("active", p.getAttribute("data-step") == n);
  });
  $$(".prog-dot").forEach(function (d) {
    d.classList.toggle(
      "active",
      parseInt(d.getAttribute("data-dot"), 10) <= Math.min(n, 3),
    );
  });
  $("#stepLabel").textContent = n === 4 ? "Confirmed" : "Step " + n + " of 3";
  $("#btnBack").disabled = n === 1;
  $("#btnNext").textContent = n === 3 ? "Confirm Reservation" : "Continue";
  $("#reserveFoot").style.display = n === 4 ? "none" : "flex";
  hideError();
  if (n === 2) buildSlots();
  if (n === 3) updateSummary();
  $(".modal-body", reserveModal).scrollTop = 0;
}
function validateStep() {
  if (curStep === 1) {
    if (!res.date) {
      showError("Please choose a date.");
      return false;
    }
    if (!slotRange(res.date, res.period)) {
      showError("We are closed on Mondays — please pick another date.");
      return false;
    }
  }
  if (curStep === 2 && !res.slot) {
    showError("Please select a time.");
    return false;
  }
  if (curStep === 3) {
    if ($("#resName").value.trim().length < 2) {
      showError("Please tell us your name.");
      return false;
    }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test($("#resEmail").value.trim())) {
      showError("Please enter a valid email.");
      return false;
    }
  }
  return true;
}
$("#btnNext").addEventListener("click", function () {
  if (!validateStep()) return;
  if (curStep < 3) {
    goStep(curStep + 1);
    return;
  }
  $("#successName").textContent = $("#resName").value.trim().split(" ")[0];
  $("#successEmail").textContent = $("#resEmail").value.trim();
  $("#successDate").textContent = fmtDate(res.date);
  $("#successTime").textContent =
    res.slot + " · " + (res.period === "lunch" ? "Lunch" : "Dinner");
  $("#successGuests").textContent =
    res.guestsLabel + (res.guests === 1 ? " guest" : " guests");
  goStep(4);
});
$("#btnBack").addEventListener("click", function () {
  if (curStep > 1) goStep(curStep - 1);
});
$$("#guestPills .slot-pill").forEach(function (b) {
  b.addEventListener("click", function () {
    $$("#guestPills .slot-pill").forEach(function (x) {
      x.classList.remove("selected");
    });
    b.classList.add("selected");
    res.guests = parseInt(b.getAttribute("data-guests"), 10);
    res.guestsLabel =
      b.getAttribute("data-guests") === "6"
        ? "6+"
        : b.getAttribute("data-guests");
  });
});
$$("#periodPills .slot-pill").forEach(function (b) {
  b.addEventListener("click", function () {
    $$("#periodPills .slot-pill").forEach(function (x) {
      x.classList.remove("selected");
    });
    b.classList.add("selected");
    res.period = b.getAttribute("data-period");
  });
});
var dateInput = $("#resDate");
(function () {
  var today = new Date();
  var iso = function (d) {
    return (
      d.getFullYear() +
      "-" +
      ("0" + (d.getMonth() + 1)).slice(-2) +
      "-" +
      ("0" + d.getDate()).slice(-2)
    );
  };
  dateInput.min = iso(today);
  var def = new Date(today);
  def.setDate(def.getDate() + 2);
  if (def.getDay() === 1) def.setDate(def.getDate() + 1);
  dateInput.value = iso(def);
  res.date = dateInput.value;
})();
dateInput.addEventListener("change", function () {
  res.date = this.value;
  hideError();
});
function openReserve() {
  closeMobile();
  goStep(1);
  reserveModal.classList.add("open");
  lockScroll(true);
}
function closeReserve() {
  reserveModal.classList.remove("open");
  lockScroll(false);
}
function bindReserve() {
  $$("[data-reserve]").forEach(function (b) {
    if (!b._rb) {
      b._rb = 1;
      b.addEventListener("click", openReserve);
    }
  });
}
bindReserve();
$$("[data-close-reserve]").forEach(function (el) {
  el.addEventListener("click", closeReserve);
});
document.addEventListener("keydown", function (e) {
  if (e.key === "Escape") {
    if (reserveModal.classList.contains("open")) closeReserve();
    if (dishModal.classList.contains("open")) closeDish();
    if (filmModal.classList.contains("open")) closeFilm();
    closeMobile();
  }
});

/* motion: hero intro, reveals, layered parallax */
if (hasGsap && typeof ScrollTrigger !== "undefined" && !reducedMotion) {
  gsap.from("[data-hero]", {
    y: 52,
    opacity: 0,
    duration: 1.25,
    stagger: 0.14,
    ease: "power3.out",
    delay: 0.15,
    clearProps: "opacity",
  });
  gsap.utils.toArray("[data-reveal]").forEach(function (el) {
    gsap.from(el, {
      y: 40,
      opacity: 0,
      duration: 1.05,
      ease: "power3.out",
      scrollTrigger: { trigger: el, start: "top 90%" },
    });
  });
  /* hero layers drift at different rates */
  gsap.to("#heroImg", {
    yPercent: 12,
    ease: "none",
    scrollTrigger: {
      trigger: "#home",
      start: "top top",
      end: "bottom top",
      scrub: true,
    },
  });
  gsap.to(".hero-title", {
    yPercent: -46,
    ease: "none",
    scrollTrigger: {
      trigger: "#home",
      start: "top top",
      end: "bottom top",
      scrub: true,
    },
  });
  gsap.to(".hero-eyebrow", {
    yPercent: -90,
    opacity: 0.25,
    ease: "none",
    scrollTrigger: {
      trigger: "#home",
      start: "top top",
      end: "bottom top",
      scrub: true,
    },
  });
  gsap.to(".hero-inner", {
    y: -34,
    ease: "none",
    scrollTrigger: {
      trigger: "#home",
      start: "top top",
      end: "bottom top",
      scrub: true,
    },
  });
  /* generic image parallax */
  gsap.utils.toArray("[data-plx]").forEach(function (img) {
    gsap.fromTo(
      img,
      { yPercent: -5 },
      {
        yPercent: 5,
        ease: "none",
        scrollTrigger: {
          trigger: img,
          start: "top bottom",
          end: "bottom top",
          scrub: true,
        },
      },
    );
  });
  /* collection card image — slower drift inside its frame */
  gsap.utils.toArray(".col-card .ph img").forEach(function (img) {
    gsap.fromTo(
      img,
      { yPercent: -4 },
      {
        yPercent: 4,
        ease: "none",
        scrollTrigger: {
          trigger: img,
          start: "top bottom",
          end: "bottom top",
          scrub: true,
        },
      },
    );
  });
  /* story pair — the two frames drift against each other */
  gsap.to(".ph-1", {
    y: -26,
    ease: "none",
    scrollTrigger: {
      trigger: ".story-imgs",
      start: "top bottom",
      end: "bottom top",
      scrub: true,
    },
  });
  gsap.to(".ph-2", {
    y: 30,
    ease: "none",
    scrollTrigger: {
      trigger: ".story-imgs",
      start: "top bottom",
      end: "bottom top",
      scrub: true,
    },
  });
  /* quotes drift gently as they pass */
  gsap.fromTo(
    ".quotes .wrap",
    { y: 26 },
    {
      y: -26,
      ease: "none",
      scrollTrigger: {
        trigger: ".quotes",
        start: "top bottom",
        end: "bottom top",
        scrub: true,
      },
    },
  );
  /* ethos statement — slow settle */
  gsap.fromTo(
    ".ethos p",
    { y: 30 },
    {
      y: -18,
      ease: "none",
      scrollTrigger: {
        trigger: ".ethos",
        start: "top bottom",
        end: "bottom top",
        scrub: true,
      },
    },
  );
  /* hero mouse parallax — photo and headline ease against the cursor */
  if (finePointer) {
    var hxTo = gsap.quickTo("#heroImg", "x", { duration: 1.1, ease: "power3" }),
      hyTo = gsap.quickTo("#heroImg", "y", { duration: 1.1, ease: "power3" });
    var txTo = gsap.quickTo(".hero-title", "x", {
      duration: 1.3,
      ease: "power3",
    });
    $("#home").addEventListener("mousemove", function (e) {
      var nx = e.clientX / window.innerWidth - 0.5,
        ny = e.clientY / window.innerHeight - 0.5;
      hxTo(nx * -18);
      hyTo(ny * -10);
      txTo(nx * 12);
    });
  }
}
addEventListener("load", function () {
  if (typeof ScrollTrigger !== "undefined")
    setTimeout(function () {
      ScrollTrigger.refresh();
    }, 400);
});
